package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import com.lianxibu.site.domain.protocol.CanonicalJson;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.repository.sources.JdbcSourceRunAnalysis;
import com.lianxibu.site.service.sources.SourceRunAnalysisService;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** Actual original partial providers; retained fictional outcomes without external calls. */
class SourcePartialParentStepTest {
    SourcePartialPlanCoordinatorTest q;GenerationJdbcStoreTest db;SourceStageResolutionService resolutions;SourceDedupPartialSealService p1;
    SourceValuePartialSealService p2;SourceValueFinalizationService finals;SourceValueFinalAvailabilityService observer;SourceAnalysisParentStepService service;Clock clock;
    GenerationJdbcStoreTest database(){return new GenerationJdbcStoreTest();}
    SourcePartialPlanCoordinatorTest coordinatorFixture(){return new SourcePartialPlanCoordinatorTest(){@Override GenerationJdbcStoreTest database(){return SourcePartialParentStepTest.this.database();}};}
    void setup(int count,boolean mixed)throws Exception{
        q=coordinatorFixture();q.setup(count,mixed);wire();
    }
    void wire(){db=q.db;clock=q.clock;
        var tx=new DataSourceTransactionManager(db.source);var deps=new SourceDedupDependencyService(q.q.a.observations,q.q.a.proven,q.q.a.service);var results=new JdbcSourceDedupResults(db.source);var values=new SourceValueResultProofService(results,q.plans,q.q.h.f.p1.universes,deps);
        resolutions=new SourceStageResolutionService(new JdbcSourceStageRoots(db.source),q.plans,q.q.h.f.p1.universes,q.parts,new JdbcFrozenInputs(db.source),results,new SourceDedupResultProofService(results,q.plans,q.q.h.f.p1.universes),values,deps);
        p1=q.q.a.a.f.service;var archives=new SourceValuePartialArchiveService(resolutions,new JdbcSourceValuePartialBlocks(db.source),db.writes,tx,clock);var seals=new JdbcSourceValuePartialReceipts(db.source);p2=new SourceValuePartialSealService(resolutions,archives,seals,new JdbcSourceStageRoots(db.source),db.writes,tx,clock,q.q.a.service);
        var whole=new SourceValueStageProofService(q.plans,q.q.h.f.p1.universes,values,deps,p2);var proof=new SourceValueFinalProofService(whole,q.plans,q.q.h.f.p1.universes);var finalArchives=new SourceValueFinalArchiveService(proof,new JdbcSourceValueFinalBlocks(db.source),db.writes,tx,clock);var receipts=new SourceValueFinalReceiptService(new JdbcSourceValueFinalReceipts(db.source));
        var permits=new SourceValuePartialCommitPermitService(p2,resolutions,new JdbcSourceValuePartialBlocks(db.source),seals,new JdbcSourceStageRoots(db.source),q.q.a.service,tx);
        finals=new SourceValueFinalizationService(proof,finalArchives,q.plans,q.q.h.f.p1.universes,receipts,new SourceRunAnalysisService(new JdbcSourceRunAnalysis(db.source),receipts::prior),db.writes,tx,clock,permits);observer=new SourceValueFinalAvailabilityService(finals,new JdbcSourceValueFinalAvailability(db.source),db.writes,tx,clock);service=provider(p1,p2);
    }
    SourceAnalysisParentStepService provider(SourceDedupPartialSealService dedup,SourceValuePartialSealService value){return new SourceAnalysisParentStepService(new SourceIntentOriginService(new JdbcSourceIntentScan(db.source),q.q.h.metadata),new JdbcFrozenSourcePlans(db.source),q.plans,q.parts,q.service,resolutions,q.q.service,finals,observer,new DataSourceTransactionManager(db.source),clock,dedup,value);}
    <T>T read(java.util.function.Supplier<T> work){var tx=new TransactionTemplate(new DataSourceTransactionManager(db.source));tx.setReadOnly(true);return tx.execute(s->work.get());}
    JdbcSourceIntentScan.Candidate candidate(String id){return read(()->new JdbcSourceIntentScan(db.source).page(null,50).candidates().stream().filter(c->id.equals(c.id())).findFirst().orElseThrow());}
    FrozenSourceStagePlan.Reference ref(){return read(()->FrozenSourceStagePlan.Reference.fromJson(JdbcFrozenInputs.canonical(CanonicalJson.parse(new JdbcFrozenSourcePlans(db.source).immutableReceipt(q.intent).payloadJson()).get("plan_ref"))));}
    void status(SourceAnalysisParentStepService.Status status,String id){assertEquals(status,service.step(candidate(id)).status());}
    void complete(boolean applied){var f=new SourceValueStageProofTest();f.f=db;f.plan=read(()->q.plans.readImmutable(ref()));f.original=read(()->q.q.h.f.p1.universes.readImmutable(f.plan.reference()));f.clock=clock;f.pure=new SourceValueStageResultTest();for(int n=0;n<f.plan.chunks().size();n++){if(applied)f.complete(n);else db.jdbc.update("UPDATE jobs SET state='failed',revision=revision+1,call_count=3 WHERE id=?",f.plan.chunks().get(n).rootId());}}
    String collector(String field){return JdbcFrozenInputs.canonical(CanonicalJson.parse(db.jdbc.queryForObject("SELECT "+field+" FROM source_runs",String.class)));}
    @Test void PartialParentUsesActualOriginalHandoffAndSealsBothAppliedAndFailedValueResults()throws Exception{
        for(boolean applied:List.of(true,false)){setup(101,true);String result=collector("result_json"),coverage=collector("coverage_json");status(SourceAnalysisParentStepService.Status.PREPARED,q.intent);status(SourceAnalysisParentStepService.Status.PENDING,q.intent);var plan=read(()->q.plans.readImmutable(ref()));for(int n=1;n<plan.chunks().size();n++)status(SourceAnalysisParentStepService.Status.PREPARED,q.intent);complete(applied);int calls=db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class);assertNull(read(()->p2.readCommitted(ref())));status(SourceAnalysisParentStepService.Status.FINALIZED,q.intent);assertNotNull(read(()->p2.readCommitted(ref())));assertNotNull(read(()->finals.readCommitted(ref())));assertEquals("partial",db.jdbc.queryForObject("SELECT analysis_state FROM source_runs",String.class));assertEquals("succeeded",db.jdbc.queryForObject("SELECT state FROM jobs WHERE id=?",String.class,q.intent));assertEquals("failed",db.jdbc.queryForObject("SELECT state FROM jobs WHERE id=?",String.class,q.q.a.f.plan.chunks().getLast().rootId()));assertEquals(calls,db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));assertEquals(result,collector("result_json"));assertEquals(coverage,collector("coverage_json"));int rows=db.count("1=1"),settings=q.settings;long revision=db.jdbc.queryForObject("SELECT revision FROM source_runs",Long.class);q.allowed=false;db.jdbc.execute("DROP TABLE source_run_items");db.jdbc.execute("DROP TABLE analyzed_entities");service=provider(p1,p2);status(SourceAnalysisParentStepService.Status.FINALIZED,q.intent);assertEquals(rows,db.count("1=1"));assertEquals(settings,q.settings);assertEquals(revision,db.jdbc.queryForObject("SELECT revision FROM source_runs",Long.class));}
    }
    @Test void AllFailedP1CreatesZeroValueAndTerminalRestartRecoversOnlyMissingFirstObservation()throws Exception{
        setup(1,false);status(SourceAnalysisParentStepService.Status.PREPARED,q.intent);var reference=ref();assertTrue(read(()->q.plans.readImmutable(reference)).chunks().isEmpty());assertEquals(0,db.count("record_kind='logical_task' AND task_type='news_value'"));p2.seal(reference);assertNotNull(finals.finish(reference));assertEquals(0,db.count("target_type='source_value_final_availability'"));q.allowed=false;clock=Clock.fixed(clock.instant().plusSeconds(60),ZoneOffset.UTC);observer=new SourceValueFinalAvailabilityService(finals,new JdbcSourceValueFinalAvailability(db.source),db.writes,new DataSourceTransactionManager(db.source),clock);service=provider(p1,p2);status(SourceAnalysisParentStepService.Status.FINALIZED,q.intent);assertEquals(1,db.count("target_type='source_value_final_availability'"));var committed=read(()->finals.readCommitted(reference));assertEquals(clock.instant(),read(()->observer.availableAt(committed,clock.instant())));assertEquals("partial",db.jdbc.queryForObject("SELECT analysis_state FROM source_runs",String.class));assertEquals("succeeded",db.jdbc.queryForObject("SELECT state FROM jobs WHERE id=?",String.class,q.intent));assertEquals(3,db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));
    }
    @Test void MissingPortsCapacityTransactionsAndOriginalChangesCannotClaimCompletion()throws Exception{
        setup(1,false);service=provider(null,null);assertThrows(RuntimeException.class,()->service.step(candidate(q.intent)));assertNull(read(()->new JdbcFrozenSourcePlans(db.source).immutableReceipt(q.intent)));service=provider(p1,p2);status(SourceAnalysisParentStepService.Status.PREPARED,q.intent);service=provider(p1,null);status(SourceAnalysisParentStepService.Status.PENDING,q.intent);assertEquals(0,db.count("target_type='source_value_final_result'"));var capped=spy(p2);doThrow(new GenerationFlowService.CapacityGuarded()).when(capped).seal(any());service=provider(p1,capped);status(SourceAnalysisParentStepService.Status.GATED,q.intent);service=provider(p1,p2);assertThrows(RuntimeException.class,()->q.q.h.f.p1.tx(()->service.step(candidate(q.intent))));db.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE id=?",q.q.a.f.plan.chunks().getFirst().rootId());assertThrows(RuntimeException.class,()->service.step(candidate(q.intent)));assertEquals(0,db.count("target_type='source_value_final_result'"));
    }
    @Test void SealAndFinalReceiptFaultsLeaveNoFalseProjectionAndResumeFromActualPlan()throws Exception{
        setup(1,false);status(SourceAnalysisParentStepService.Status.PREPARED,q.intent);db.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_parent_partial_seal CHECK(target_type IS NULL OR target_type<>'source_value_partial_result')");assertThrows(RuntimeException.class,()->service.step(candidate(q.intent)));assertEquals(0,db.count("target_type='source_value_final_result'"));drop("fictional_parent_partial_seal");db.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_parent_partial_final CHECK(target_type IS NULL OR target_type<>'source_value_final_result')");assertThrows(RuntimeException.class,()->service.step(candidate(q.intent)));assertNotNull(read(()->p2.readCommitted(ref())));assertNull(db.jdbc.queryForObject("SELECT analysis_summary FROM source_runs",String.class));assertEquals("waiting_input",db.jdbc.queryForObject("SELECT state FROM jobs WHERE id=?",String.class,q.intent));drop("fictional_parent_partial_final");service=provider(p1,p2);status(SourceAnalysisParentStepService.Status.FINALIZED,q.intent);assertEquals(1,db.count("target_type='source_value_final_result'"));assertEquals(1,db.count("target_type='source_value_final_availability'"));
    }
    @Test void ActualQueuedP1PartialParentCreatesItsSealBeforeTheOnlyHandoff()throws Exception{
        q=new SourcePartialPlanCoordinatorTest(){@Override GenerationJdbcStoreTest database(){return SourcePartialParentStepTest.this.database();}};
        q.q=new SourceValuePartialIntentHandoffTest(){@Override GenerationJdbcStoreTest database(){return SourcePartialParentStepTest.this.database();}};q.q.setup(101,true);q.db=q.q.h.f.f;q.clock=Clock.fixed(q.q.h.f.clock.instant().plusSeconds(60),ZoneOffset.UTC);q.plans=new FrozenSourceStagePlanService(new JdbcFrozenSourcePlans(q.db.source),q.q.h.f.p1.universes,q.clock,"fictional-owner");q.service=q.provider(q.db.writes,q.q.a.service);wire();
        db.jdbc.update("DELETE FROM jobs WHERE id=? OR target_type='source_stage_availability'",JdbcSourceDedupPartialReceipts.receiptId(q.q.h.ref.ownerId()));assertNull(read(()->p1.readCommitted(q.q.h.ref)));assertEquals(0,q.q.h.children());int calls=db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class);status(SourceAnalysisParentStepService.Status.HANDED_OFF,q.q.h.ref.ownerId());assertNotNull(read(()->p1.readCommitted(q.q.h.ref)));assertEquals(1,q.q.h.children());assertEquals(1,q.q.h.relations());assertEquals("succeeded",q.q.h.state());assertEquals("failed",db.jdbc.queryForObject("SELECT state FROM jobs WHERE id=?",String.class,q.q.a.f.plan.chunks().getLast().rootId()));assertEquals(calls,db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));
    }
    void drop(String name){db.jdbc.execute("ALTER TABLE jobs"+(db.source instanceof org.h2.jdbcx.JdbcDataSource?" DROP CONSTRAINT ":" DROP CHECK ")+name);}
}
